// Finds the largest element in the array 
int findLargestElement(int arr[], int n) 
{ 
	// Initialize maximum element 
	int max = arr[0]; 

	// Traverse array elements from second and 
	// compare every element with current max 
	for (int i = 1; i < n; i++) 
		if (arr[i] > max) 
			max = arr[i]; 

	return max; 
} 

