        self.last_occurrence = -1

    def findFirstLastOccurrence(self, k):
        #Find the first occurrence
        left = 0
        right = len(self.arr) - 1
        while left <= right:
            mid = (left + right) // 2
            if self.arr[mid] == k and (mid == 0 or self.arr[mid-1] < k):
                self.first_occurrence = mid
                break
            elif self.arr[mid] < k:
                left = mid+1
            else:
