int maxSum = 0;

// traverse elements in upper-left 
// to lower-right diagonal order 
for (int i = 0; i < Matrix.size(); i++ )
{
    int sum = 0; 
    // traverse diagonal element 
    for (int j = 0; (i+j) < Matrix.size() && j < Matrix.size(); j++ )
        sum += Matrix[i+j][j]; 
    // update max sum 
    maxSum = max(maxSum, sum); 
} 

// traverse elements in upper-right 
// to lower-left diagonal order 
for (int i = 1; i < Matrix.size(); i++ ) 
{ 
    int sum = 0; 
    // traverse diagonal element 
    for (int j = 0; (i+j) < Matrix.size() && j < Matrix.size(); j++ ) 
        sum += Matrix[j][i+j]; 
    // update max sum 
    maxSum = max(maxSum, sum); 
}

