def prime_numbers_in_range(a, b):
    """
    Displays all prime numbers between a given range.
    """
    for num in range(a, b+1):
        if is_prime(num):
            print(num,' is prime.')

def is_prime(num):
    """
    Checks if a number is prime or not.
    """
    if num == 1:
        return False
    else:
        for i in range(2, num):
            if num % i == 0:
                return False 
    return True

