def cached(timeout=CACHE_TIMEOUT, key='view/%s'):
    def decorator(f):
        @wraps(f)
        def decorated_function(*args, **kwargs):
            cache_key = key % request.full_path # using full path for get params
            rv = cache.get(cache_key)
            if rv is not None:
                return rv
            rv = f(*args, **kwargs)
            cache.set(cache_key, rv, timeout=timeout)
            return rv
        return decora

def count_string_occurrences(str1, str2):
    """This function takes in two strings and returns the total number of occurrences of the second string in the first string."""
    count = 0
    for i in range(len(str1) - len(str2) + 1):
        if str1[i:i + len(str2)] == str2:
            count += 1
    return count

