class SampleSet(collections.MutableSet):
    def __init__(self):
        self._dict = {}
        self._len = 0

    def __contains__(self, sample):
        try:
            return reduce(lambda d, k: d[k], sample, self._dict)
        except KeyError:
            return False

    def __len__(self):
        return self._len

    def add(self, sample):
        d = self._dict
        for i, s in enumerate(sample):
            if i == len(sample) - 1:
                d[s] = True
                continue
            if s not in d:
                d[s] = {}
            d = d[s]
        self._len += 1

    def discard(self, sample):
        pass

    def __iter__(self):
        pass


