def mergesort(nums): 
    if len(nums) == 1: 
        return nums 

    mid = len(nums) // 2
    left_list = nums[:mid] 
    right_list = nums[mid:] 

    left_list = mergesort(left_list) 
    right_list = mergesort(right_list) 
    return merge(left_list, right_list) 

