class File:
    def __init__(self, path):
        self.fh = open(path, "r+")
        try:
            self.fstring = self.fh.read()
        except UnicodeDecodeError:
            print("\033[94m" + "[SKP] {}".format(path))
            self.fstring = ""

        self.flist = self.fstring.split("\n")

    def flush(self):
        self.fstring = "\n".join(self.flist)
        self.fh.seek(0)
        self.fh.write(self.fstring)
        self.fh.close()

