def max_repeated_char(input_string):
    char_count = dict()
    max_count = 0
    max_char = None
    for char in input_string:
        if char not in char_count:
            char_count[char] = 1
        else:
            char_count[char] += 1

    for char in char_count:
        if char_count[char] > max_count:
            max_count = char_count[char]
            max_char = char
    return max_char

public static boolean isPrime(int n) 
{ 
    // Corner case 
    if (n <= 1) 
        return false; 

    // Check from 2 to n-1 
    for (int i = 2; i < n; i++) 
        if (n % i == 0) 
            return false; 

    return true; 
}

def find_sum(arr, num):
    found = False
    arr_set = set(arr)
    for i in arr_set:
        x = num - i
        if x in arr_set and x != i:  # make sure the numbers aren't the same
            found = True
            return i, x

    if not found:
        return False

