import setuptools

def package_data_dirs(source, sub_folders):
  import os
  dirs = []

  for d in sub_folders:
    for dirname, _, files in os.walk(os.path.join(source, d)):
      dirname = os.path.relpath(dirname, source)
      for f in files:
        dirs.append(os.path.join(dirname, f))

  return dirs

