def quick_sort(arr):
    """Sort a list of numbers in ascending order using the Quick-Sort algorithm"""
    if len(arr) == 0:
        return []

    pivot = arr[0]
    left_arr = [x for x in arr if x < pivot]
    right_arr = [x for x in arr if x > pivot]
    return quick_sort(left_arr) + [pivot] + quick_sort(right_arr)

function areAnagrams(str1, str2) {
  if (str1.length !== str2.length) {
    return false;
  }
  let charMap1 = {};
  let charMap2 = {};

  for(let i = 0; i < str1.length; i++) {
    if(!charMap1[str1.charAt(i)]) {
      charMap1[str1.charAt(i)] = 1;
    } else { 
      charMap1[str1.charAt(i)]++;
    }

    if(!charMap2[str2.charAt(i)]) {
      charMap2[str2.charAt(i)] = 1;
    } else { 
      charMap2[str2.charAt(i)]++;
    }
  }

  for(let key in charMap1) {
    if (charMap1[key] != charMap2[key]) {
      return false;
    }
  }

  return true;

}

function maxmin(nums) {  
    let max = nums[0];
    let min = nums[0];

    for (let i = 0; i < nums.length; i++) {
        // comparison to find the maximum
        if (nums[i] > max) {
            max = nums[i];
        }
        // comparison to find the minimum
        if (nums[i] < min) {
            min = nums[i];
        }
    }

    return {max:max, min:min};  
}

