def lowest_common_multiple(x, y): 
    if x > y:
        greater = x
    else:
        greater = y
    while(True): 
        if((greater % x == 0) and (greater % y == 0)): 
            lcm = greater 
            break
        greater += 1
    return lcm

def find_greatest_difference(arr):
  max_diff = 0
  for i in range(len(arr)):
    for j in range(i+1, len(arr)):
      diff = abs(arr[i] - arr[j])
      if diff > max_diff:
        max_diff = diff

  return max_diff

